"""PSLE-style items for sci-energy-photo-requirements, all tiers (round sci-fill-photo-req-2026-11-20)."""
from fillkit import add, table, graph, lint
from figs_photo import leaf, jar, pondweed, tubes

SUB, FILE = "sci-energy-photo-requirements", "sci-photo-req.json"
PH, FT, RD = "sci-pat-photosynthesis", "sci-pat-fair-test-design", "sci-pat-read-data"
B, I, C = "basic", "intermediate", "competent"
P = []
def q(*a): P.append(a)
def W(t, tag, why): return (t, tag, why)
def tb(h, r, w, c): return lambda: table(h, r, w, c)

# ---------------- basic ----------------
q("ph-001", B, 1, PH, "Which of the following does a green plant need to make food by photosynthesis?", "Light, water and carbon dioxide", [W("Light, oxygen and sugar", "wrong-need", "Oxygen and sugar are made by the plant. They are not what it needs to start."), W("Water, oxygen and soil", "wrong-need", "Oxygen is not a raw material, and light is needed too."), W("Carbon dioxide, sugar and soil", "wrong-need", "Sugar is made by photosynthesis, so it is not a requirement.")], ["Photosynthesis needs light energy, water and carbon dioxide."], None)
q("ph-002", B, 1, PH, "Which gas does a plant take in from the air for photosynthesis?", "Carbon dioxide", [W("Oxygen", "wrong-gas", "Oxygen is given out by photosynthesis."), W("Nitrogen", "wrong-gas", "Plants do not use nitrogen gas to make food."), W("Water vapour", "wrong-gas", "Plants take in liquid water through the roots, not water vapour for food.")], ["The plant takes in carbon dioxide from the air."], None)
q("ph-003", B, 1, PH, "Which gas is given out by a plant during photosynthesis?", "Oxygen", [W("Carbon dioxide", "wrong-gas", "This is taken in by the plant."), W("Nitrogen", "wrong-gas", "Photosynthesis does not give out nitrogen."), W("Hydrogen", "wrong-gas", "Photosynthesis does not give out hydrogen.")], ["Oxygen is a product of photosynthesis."], None)
q("ph-004", B, 1, PH, "Which of the following is the food made by a plant in photosynthesis?", "Sugar", [W("Oxygen", "wrong-product", "Oxygen is a gas given out. It is not food."), W("Carbon dioxide", "wrong-product", "Carbon dioxide is taken in as a raw material."), W("Water", "wrong-product", "Water is taken in as a raw material.")], ["Photosynthesis makes sugar, which the plant uses as food."], None)
q("ph-005", B, 1, PH, "Which part of a plant mainly makes food by photosynthesis?", "The leaves", [W("The roots", "wrong-part", "Roots take in water. They are underground and get no light."), W("The stem", "wrong-part", "The stem carries water and sugar. It does not mainly make food."), W("The seeds", "wrong-part", "Seeds can grow into new plants. They do not mainly make food.")], ["Leaves are flat and take in a lot of light, so most food is made there."], None)
q("ph-006", B, 1, PH, "Which form of energy do plants need to make food?", "Light energy", [W("Sound energy", "wrong-form", "Plants do not use sound to make food."), W("Kinetic energy", "wrong-form", "Plants do not need movement energy to make food."), W("Electrical energy", "wrong-form", "Plants do not use electricity to make food.")], ["Plants use light energy, usually from the Sun."], None)
q("ph-007", B, 1, PH, "From where does a plant take in the water it uses for photosynthesis?", "The soil, through its roots", [W("The air, through its leaves", "wrong-source", "Most of the water comes from the soil."), W("The Sun, through its stem", "wrong-source", "The Sun gives light, not water."), W("The flowers, from rain", "wrong-source", "Flowers do not take in water for food.")], ["Roots take in water, which travels up the stem to the leaves."], None)
q("ph-008", B, 1, PH, "A potted plant is kept in a dark cupboard for many days. What will happen to the plant?", "It cannot make food and becomes weak", [W("It makes more food than before", "wrong-idea", "Without light a plant cannot make food."), W("It makes more oxygen than before", "wrong-idea", "Oxygen is given out only when photosynthesis takes place."), W("It grows stronger and taller", "wrong-idea", "Without food the plant becomes weak.")], ["Without light, photosynthesis cannot take place."], None)
q("ph-009", B, 1, PH, "Why do plants need light?", "To get energy to make food", [W("To breathe in oxygen", "wrong-reason", "Light is not breathed in."), W("To take in water from the soil", "wrong-reason", "Roots take in water without light."), W("To make carbon dioxide", "wrong-reason", "Plants take in carbon dioxide. They do not make it for food.")], ["Light provides the energy for photosynthesis."], None)
q("ph-010", B, 1, PH, "Which equation correctly shows photosynthesis?", "Carbon dioxide + water, in light, makes sugar + oxygen", [W("Sugar + oxygen, in light, makes carbon dioxide + water", "reversed", "This is the wrong way round. Plants make sugar from carbon dioxide and water."), W("Oxygen + water, in light, makes sugar + carbon dioxide", "wrong-gas", "Oxygen is given out, and carbon dioxide is taken in."), W("Sugar + water, in light, makes oxygen + carbon dioxide", "wrong-gas", "Sugar is a product, not a raw material.")], ["Raw materials: carbon dioxide and water. Products: sugar and oxygen."], None)
q("ph-011", B, 1, PH, "Which one of the following is NOT needed by a plant for photosynthesis?", "Oxygen", [W("Light", "needed", "Light energy is needed."), W("Water", "needed", "Water is a raw material."), W("Carbon dioxide", "needed", "Carbon dioxide is a raw material.")], ["Oxygen is a product of photosynthesis, so it is not needed."], None)
q("ph-012", B, 1, PH, "A leaf is partly covered with foil and placed in bright light. Part P is covered with foil and part Q is not. Which part cannot make food?", "P", [W("Q", "wrong-part", "Part Q gets light, so it can make food."), W("Both P and Q", "wrong-part", "Part Q is not covered, so it gets light."), W("Neither P nor Q", "wrong-part", "Part P is covered, so it gets no light.")], ["Foil stops light from reaching part P, so it cannot photosynthesise."], lambda: leaf([("Q", "uncovered", False), ("P", "foil", True)], "A leaf in bright light"))
q("ph-013", B, 1, PH, "In the leaf shown, why can part P not make food?", "It does not get light", [W("It does not get oxygen", "wrong-need", "Oxygen is not needed for making food."), W("It has been given far too much water", "wrong-need", "Foil does not add water."), W("It has no sugar", "wrong-need", "Part P has no sugar because it cannot make any. The missing light is the cause.")], ["The foil blocks light, so P cannot make food."], lambda: leaf([("Q", "uncovered", False), ("P", "foil", True)], "A leaf in bright light"))
q("ph-014", B, 1, PH, "The table shows four plants, all kept in a warm place. Which two plants are able to make food?", "P and S", [W("Q and R", "wrong-pair", "Q has no light and R has no water."), W("P and Q", "wrong-pair", "Q has no light."), W("R and S", "wrong-pair", "R has no water.")], ["P and S have light, water and air with carbon dioxide."], tb(["Plant", "Light", "Water"], [["P", "yes", "yes"], ["Q", "no", "yes"], ["R", "yes", "no"], ["S", "yes", "yes"]], [70, 90, 90], "Four plants (all have air)"))
q("ph-015", B, 1, PH, "A farmer wants her vegetable plants to make more food. Which of the following will help?", "Planting them where they get plenty of sunlight and water", [W("Planting them in a dark room", "reversed", "Without light plants cannot make food."), W("Keeping them away from water", "reversed", "Plants need water to make food."), W("Covering them with a plastic sheet that blocks the light", "reversed", "Blocking light stops photosynthesis.")], ["Light and water are needed for photosynthesis."], None)
q("ph-016", B, 1, PH, "When does photosynthesis mainly take place?", "In the day, when there is light", [W("At night, when the plant is in the dark", "wrong-time", "No light means no photosynthesis."), W("Only when it is raining hard", "wrong-time", "Rain is not needed, only water in the soil."), W("Only in the late evening hours", "wrong-time", "Light is needed, and it is stronger in the day.")], ["Light is needed, so photosynthesis happens in the day."], None)
q("ph-017", B, 1, PH, "A plant makes more sugar than it needs. What happens to the extra sugar?", "Some is stored as starch in roots, stems and fruits", [W("It is given out through the leaves into the air as a gas", "wrong-idea", "Sugar is not given out. Oxygen is the gas given out."), W("It is turned into water and given out from the roots", "wrong-idea", "Sugar is not turned into water."), W("It is thrown away through the roots into the soil", "wrong-idea", "The plant does not waste its food.")], ["The plant stores extra food as starch."], None)
q("ph-018", B, 1, PH, "Which of the following can make its own food?", "A grass plant", [W("A butterfly", "wrong-living", "Animals cannot make their own food."), W("A mushroom", "wrong-living", "A mushroom takes food from dead things."), W("A cat", "wrong-living", "Animals cannot make their own food.")], ["Only green plants make food using light."], None)
q("ph-019", B, 1, PH, "Which solution is used to test a leaf for starch?", "Iodine solution", [W("Salt solution", "wrong-test", "Salt does not show starch."), W("Vinegar", "wrong-test", "Vinegar does not show starch."), W("Soap solution", "wrong-test", "Soap does not show starch.")], ["Iodine solution turns blue-black when starch is present."], None)
q("ph-020", B, 1, PH, "A leaf that has been making food in the light is tested with iodine solution. What colour does the leaf turn if it has starch?", "Blue-black", [W("Yellow", "wrong-colour", "Yellow-brown is the colour of iodine when there is no starch."), W("Red", "wrong-colour", "Iodine does not turn red with starch."), W("Green", "wrong-colour", "Iodine does not turn leaves green.")], ["Starch makes iodine turn blue-black."], None)
q("ph-021", B, 1, PH, "A pondweed in bright light gives out tiny bubbles. Which gas is in the bubbles?", "Oxygen", [W("Carbon dioxide", "wrong-gas", "The pondweed takes this in."), W("Nitrogen", "wrong-gas", "Photosynthesis does not give out nitrogen."), W("Water vapour", "wrong-gas", "The bubbles are mainly oxygen, a product of photosynthesis.")], ["The bubbles are oxygen given out in photosynthesis."], lambda: pondweed(20, caption="Pondweed in bright light"))
q("ph-022", B, 1, PH, "Which gas must be dissolved in the water for a water plant to make food?", "Carbon dioxide", [W("Nitrogen", "wrong-gas", "Plants do not use nitrogen to make food."), W("Hydrogen", "wrong-gas", "Plants do not use hydrogen to make food."), W("Oxygen", "wrong-gas", "Oxygen is given out by the plant. It is not a raw material.")], ["Water plants take in dissolved carbon dioxide."], None)
q("ph-023", B, 1, PH, "Which gas that animals need to breathe is added to the air by plants in the day?", "Oxygen", [W("Carbon dioxide", "wrong-gas", "Plants take this in during the day."), W("Nitrogen", "wrong-gas", "Plants do not add nitrogen."), W("Hydrogen", "wrong-gas", "Plants do not give out hydrogen.")], ["Plants give out oxygen when they make food in the light."], None)
q("ph-024", B, 1, PH, "A plant on a window sill gets plenty of light but no water for a week. What will most likely happen?", "It cannot make enough food and it wilts", [W("It makes more food than before", "wrong-idea", "Water is a raw material, so less water means less food."), W("It gives out more oxygen than before", "wrong-idea", "Less food made means less oxygen given out."), W("It takes in more water through its leaves", "wrong-idea", "Without water in the soil it cannot take in more.")], ["Without water, photosynthesis slows down or stops."], None)
q("ph-025", B, 1, PH, "Why are the leaves of a plant usually flat and wide?", "To catch more light", [W("To take in more water from the air", "wrong-reason", "Most water is taken in by the roots."), W("To make the plant heavier", "wrong-reason", "Leaf shape does not add weight."), W("To keep out carbon dioxide", "wrong-reason", "Leaves take carbon dioxide in.")], ["A big flat surface takes in more light for photosynthesis."], None)

