LS = lambda: leaf([("P", "white", False), ("Q", "green", False), ("R", "green", True)], "A leaf with green and white parts")
q("ph-101", I, 1, PH, "A plant is kept in the dark for a day. Then one leaf is partly covered with foil as shown and the plant is put in bright light for several hours. The leaf is then tested for starch. Which part turns blue-black?", "Q", [W("P", "wrong-part", "P is white and has no green, so it cannot make food."), W("R", "wrong-part", "R is green but it is covered with foil, so it gets no light."), W("P and R", "wrong-part", "P has no green and R gets no light, so neither makes starch.")], ["Only Q is green and gets light, so it makes starch."], LS)
q("ph-102", I, 1, PH, "In the leaf shown (P white, Q green and in light, R green and under foil), which parts cannot make starch?", "P and R", [W("Q only", "wrong-part", "Q is green and gets light, so it can make starch."), W("P only", "wrong-part", "R also cannot make starch because it gets no light."), W("Q and R", "wrong-part", "Q can make starch.")], ["P has no green part, and R is covered, so it gets no light."], LS)
q("ph-103", I, 1, PH, "A plant is kept in the dark for a day before it is used in a starch test. Why?", "To use up the starch already in the leaves", [W("To make the leaves make more starch", "wrong-reason", "No light means no starch is made."), W("To make the leaves take in more water", "wrong-reason", "Keeping a plant in the dark does not make it take in more water."), W("To kill the plant so it can be tested", "wrong-reason", "The plant is not killed. The leaf is tested after boiling.")], ["The plant uses up its starch in the dark, so any starch found later was made during the test."], None)
q("ph-104", I, 1, PH, "A leaf is boiled in alcohol before it is tested with iodine solution. Why?", "To remove the green colour so the colour change shows", [W("To make the leaf make more starch before testing", "wrong-reason", "Boiling kills the leaf. It cannot make starch."), W("To add water to the leaf so it is soft", "wrong-reason", "Alcohol does not add water."), W("To turn the iodine solution blue-black at once", "wrong-reason", "Iodine turns blue-black only if starch is present.")], ["The green colour would hide the blue-black colour."], None)
q("ph-105", I, 1, PH, "A plant is kept in the jar shown, in bright light, for several days. The dish takes in all the carbon dioxide in the jar. What will a starch test of its leaves show?", "No starch, because there is no carbon dioxide", [W("Starch, because it has light and water", "wrong-idea", "Carbon dioxide is also needed. Without it no food is made."), W("Starch, because the dish gives it extra carbon dioxide", "wrong-idea", "The dish takes carbon dioxide in. It does not give any."), W("No starch, because the dish takes in the oxygen", "wrong-reason", "Oxygen is not needed to make starch. The missing carbon dioxide is the problem.")], ["Without carbon dioxide, photosynthesis cannot take place, so the leaves have no starch."], lambda: jar("takes in CO2", True, caption="A plant in bright light"))
q("ph-106", I, 1, PH, "Why will the plant in this jar not make starch?", "It has no light, so it cannot photosynthesise", [W("It has been given far too much water", "wrong-reason", "Nothing in the picture says it has too much water."), W("It has far too much carbon dioxide", "wrong-reason", "It is not short of anything but light."), W("It gives out too much oxygen in the box", "wrong-reason", "It gives out no oxygen without light.")], ["The dark box blocks the light."], lambda: jar(None, False, caption="Plant in a dark box for several days"))
BUB = tb(["Distance of lamp (cm)", "Bubbles per minute"], [["10", "48"], ["20", "24"], ["30", "12"], ["40", "6"]], [150, 140], "Pondweed under a lamp")
q("ph-107", I, 1, PH, "The table shows the bubbles given out by pondweed when a lamp is placed at different distances. What can be concluded?", "The nearer the lamp, the more bubbles the pondweed gives out", [W("The nearer the lamp, the fewer bubbles the pondweed gives out", "reversed", "The nearest lamp (10 cm) gave the most bubbles."), W("The distance of the lamp does not affect the number of bubbles", "wrong-reading", "The number of bubbles changes with the distance."), W("The pondweed gives out bubbles only when the lamp is 10 cm away", "wrong-reading", "Bubbles were given out at every distance.")], ["More light makes photosynthesis faster, so more oxygen bubbles are given out."], BUB)
q("ph-108", I, 1, FT, "In the same experiment, what is the variable that was measured?", "The number of bubbles per minute", [W("The distance of the lamp from the pondweed", "changed-variable", "This was changed on purpose."), W("The type of pondweed", "fixed-variable", "This was kept the same."), W("The temperature of the water", "fixed-variable", "This was kept the same.")], ["The bubbles per minute are what were counted."], BUB)
q("ph-109", I, 1, FT, "In the same experiment, which of the following should be kept the same?", "The type of pondweed and the amount of water", [W("The distance of the lamp from the pondweed", "changed-variable", "This is the variable being tested."), W("The number of bubbles counted each minute", "measured-variable", "This is the result that is measured."), W("The result at the end of the test", "measured-variable", "The result is what is found out, so it cannot be kept the same.")], ["Only the lamp distance should change."], BUB)
SET = tb(["Set-up", "Light", "Carbon dioxide", "Leaf starch test"], [["P", "yes", "yes", "blue-black"], ["Q", "no", "yes", "stays brown"], ["R", "yes", "no", "stays brown"], ["S", "no", "no", "stays brown"]], [60, 70, 120, 120], "Four plants")
q("ph-110", I, 1, FT, "The table shows the results of testing leaves of four plants. Which two plants show that light is needed to make starch?", "P and Q", [W("P and R", "wrong-pair", "P and R differ in carbon dioxide, not light."), W("Q and S", "wrong-pair", "Neither has light, so they do not test light."), W("R and S", "wrong-pair", "R and S differ in light, but both have no carbon dioxide, so neither could make starch anyway.")], ["P and Q differ only in light."], SET)
q("ph-111", I, 1, FT, "Using the same table, which two plants show that carbon dioxide is needed to make starch?", "P and R", [W("P and Q", "wrong-pair", "P and Q differ in light, not carbon dioxide."), W("Q and R", "wrong-pair", "They differ in both light and carbon dioxide."), W("Q and S", "wrong-pair", "Neither has light, so they do not test carbon dioxide.")], ["P and R differ only in carbon dioxide."], SET)
q("ph-112", I, 1, PH, "Which of the following statements about photosynthesis are correct?\nA: It needs light energy.\nB: It gives out oxygen.\nC: It takes place at night.\nD: It makes sugar.", "A, B and D only", [W("A, B and C only", "wrong-idea", "It does not take place at night, so C is wrong."), W("B, C and D only", "wrong-idea", "C is wrong because it needs light."), W("A, C and D only", "wrong-idea", "C is wrong because it needs light.")], ["Photosynthesis needs light, makes sugar and gives out oxygen."], None)
BR = lambda: graph(["1", "2", "3", "4", "5"], [("b", [10, 20, 30, 40, 50])], 60, "Brightness of the lamp", "Bubbles per minute", "Pondweed and brightness", ystep=10, W=360, H=250)
q("ph-113", I, 1, RD, "The graph shows the bubbles given out by pondweed under lamps of different brightness. Which conclusion is correct?", "The brighter the light, the faster the pondweed makes food", [W("The brighter the light, the slower the pondweed makes food", "reversed", "The line rises as the brightness rises."), W("The brightness has no effect on the pondweed", "wrong-reading", "The number of bubbles changes with brightness."), W("The pondweed makes food only in the brightest light", "wrong-reading", "Bubbles are given out at every brightness.")], ["More bubbles means faster photosynthesis. The line rises with brightness."], BR)
q("ph-114", I, 1, PH, "A plant is sealed in a clear glass jar and placed in bright light. It stays alive for many weeks. Which statement best explains this?", "It uses light to make food and oxygen from water and carbon dioxide", [W("It takes in food from the glass of the jar", "wrong-idea", "Glass does not give food."), W("It uses the oxygen it gives out to make food", "wrong-idea", "Oxygen is not a raw material for food."), W("It needs no light, water or air to live", "wrong-idea", "A plant needs light, water and carbon dioxide.")], ["The plant makes food in the light and the water and gases in the jar are reused."], None)
q("ph-115", I, 1, PH, "The leaves of a plant that was kept in a dark cupboard for two weeks turn pale. Why?", "It could not make food in the dark", [W("It made too much food in the dark", "wrong-idea", "Without light it makes no food."), W("It took in too much carbon dioxide", "wrong-idea", "It did not take in too much of anything."), W("It had too little oxygen", "wrong-idea", "Oxygen was not what it was missing. Light was.")], ["Without light there is no photosynthesis."], None)
q("ph-116", I, 1, PH, "Small plants grow poorly on the floor of a thick forest. What is the most likely reason?", "They get very little light for photosynthesis", [W("They get far too much light from above", "reversed", "The forest floor is shady."), W("They are surrounded by far too much carbon dioxide", "wrong-idea", "Carbon dioxide in the air is about the same everywhere."), W("They have no roots to take in water", "wrong-idea", "They have roots, but they lack light.")], ["The trees above block most of the light."], None)
LT = tb(["Leaf", "Covered with foil", "Starch test"], [["X", "no", "blue-black"], ["Y", "yes", "stays brown"]], [80, 130, 120], "Two leaves from the same plant")
q("ph-117", I, 1, FT, "Two leaves on a plant were tested for starch after a day in the light. The results are shown. What can be concluded?", "Light is needed for the leaf to make starch", [W("Water is needed for the leaf to make starch", "not-tested", "Water was not tested in this experiment."), W("Foil makes a leaf make starch", "wrong-idea", "The covered leaf made no starch."), W("Carbon dioxide is not needed for the leaf to make starch", "not-tested", "Carbon dioxide was not tested.")], ["The covered leaf Y got no light and had no starch."], LT)
WT = tb(["Plant", "Water", "Starch test of a leaf"], [["P", "watered each day", "blue-black"], ["Q", "not watered", "stays brown"]], [70, 130, 150], "Two plants in the same bright place")
q("ph-118", I, 1, FT, "Two plants were kept in the same bright place for a week. The table shows the results of the starch test. What can be concluded?", "Water is needed for the plant to make starch", [W("Light is needed for the plant to make starch", "not-tested", "Both plants had the same light."), W("Plants do not need water", "wrong-idea", "Plant Q did not make starch without water."), W("Carbon dioxide is needed to make starch", "not-tested", "Carbon dioxide was not changed in the test.")], ["Only the water was different, and Q made no starch."], WT)
q("ph-119", I, 1, PH, "In the day, which gas is higher in the air around a healthy plant in bright light than at night?", "Oxygen", [W("Carbon dioxide", "wrong-gas", "In the day the plant takes this in, so there is less of it."), W("Nitrogen", "wrong-gas", "The plant does not change the amount of nitrogen."), W("Hydrogen", "wrong-gas", "Plants do not give out hydrogen.")], ["The plant gives out oxygen in photosynthesis."], None)
q("ph-120", I, 1, PH, "An aquarium has fish and a water plant. How does the plant help the fish in bright light?", "It takes in carbon dioxide from the fish and gives out oxygen", [W("It takes in oxygen from the fish and gives out carbon dioxide", "reversed", "In the light the plant takes in carbon dioxide and gives out oxygen."), W("It gives out sugar into the water for the fish to breathe", "wrong-idea", "Fish breathe oxygen. Sugar is not breathed."), W("It stops the fish from giving out carbon dioxide", "wrong-idea", "The plant does not stop this.")], ["The fish give out carbon dioxide, which the plant uses. The plant gives out oxygen, which the fish breathe."], None)
q("ph-121", I, 1, PH, "Which statement about gases and plants in the day is correct?", "A plant in bright light takes in more carbon dioxide than it gives out", [W("A plant in bright light gives out more carbon dioxide than it takes in", "reversed", "Photosynthesis uses up carbon dioxide."), W("A plant in bright light takes in oxygen only", "wrong-idea", "It also gives out oxygen."), W("A plant in bright light takes in and gives out no gases", "wrong-idea", "It exchanges gases with the air.")], ["Photosynthesis uses carbon dioxide faster than the plant gives it out."], None)
q("ph-122", I, 1, PH, "A potato plant makes sugar in its leaves and stores starch in the underground potatoes. How does the sugar reach the potatoes?", "It is carried down through tubes in the stem", [W("It is carried down through the air", "wrong-idea", "Sugar does not travel through the air."), W("It leaks out of the leaves into the soil", "wrong-idea", "Sugar does not leak out of the leaves."), W("The potatoes make their own sugar from the soil", "wrong-idea", "Underground parts get no light, so they cannot photosynthesise.")], ["Tubes in the stem carry food from the leaves to other parts."], None)
q("ph-123", I, 1, PH, "Which statement describes the change in energy during photosynthesis?", "Light energy is changed into energy stored in sugar", [W("Energy stored in sugar is changed into light energy", "reversed", "This is the wrong way round. The plant takes in light."), W("Heat energy is changed into sound energy", "wrong-form", "Plants do not make sound from heat in photosynthesis."), W("Kinetic energy is changed into light energy", "wrong-form", "Photosynthesis does not use kinetic energy.")], ["The plant takes in light energy and stores it in the sugar it makes."], None)
q("ph-124", I, 1, PH, "A plant kept in the dark for two days is tested with iodine solution. What does the leaf show?", "The leaf stays brown because there is no starch", [W("The leaf turns blue-black because it has starch", "wrong-idea", "No light means no starch is made, and the old starch is used up."), W("The leaf turns red because it has sugar", "wrong-idea", "Iodine does not turn red."), W("The leaf turns green because it has water", "wrong-idea", "Iodine does not turn leaves green.")], ["In the dark the plant uses up its starch and makes no new starch."], None)
q("ph-125", I, 1, PH, "Which of the following does the sugar made by a plant help the plant to do?", "Grow and store food", [W("Take in light from the Sun", "wrong-use", "Leaves take in light without using sugar."), W("Make carbon dioxide for animals", "wrong-use", "Plants do not make carbon dioxide this way."), W("Absorb water from the air", "wrong-use", "Sugar does not help plants to absorb water from the air.")], ["Plants use sugar for energy and growth, and store the extra."], None)

# ---------------- competent ----------------
TU = lambda: tubes([("A", "pondweed", "", False), ("B", "pondweed", "", True), ("C", "no weed", "", False), ("D", "no weed", "", True)], caption="Four tubes of indicator solution")
IND = tb(["Tube", "Pondweed", "Light", "Colour after 3 h"], [["A", "yes", "yes", "purple"], ["B", "yes", "no", "yellow"], ["C", "no", "yes", "red"], ["D", "no", "no", "red"]], [50, 90, 70, 120], "Results (the indicator starts red)")
q("ph-201", C, 1, FT, "Four tubes contain the same indicator solution. A tube wrapped in foil is kept in the dark. Which two tubes should be compared to find out whether pondweed needs light to take in carbon dioxide?", "A and B", [W("A and C", "wrong-pair", "A and C differ in the pondweed, not in the light."), W("B and D", "wrong-pair", "B and D differ in the pondweed, and both are in the dark."), W("C and D", "wrong-pair", "C and D have no pondweed, so they cannot test the pondweed.")], ["A and B both have pondweed and only the light is different."], TU)
q("ph-202", C, 1, RD, "The indicator solution is yellow with much carbon dioxide, red when nothing changes, and purple with less carbon dioxide. Using the results, which tube shows that pondweed in the light takes in carbon dioxide?", "Tube A", [W("Tube B", "wrong-tube", "B is in the dark, and its indicator shows more carbon dioxide."), W("Tube C", "wrong-tube", "C has no pondweed and stays red."), W("Tube D", "wrong-tube", "D has no pondweed and stays red.")], ["In tube A the indicator turned purple, so the carbon dioxide went down."], IND)
q("ph-203", C, 1, RD, "Using the same results, why did the indicator in tube B turn yellow?", "The pondweed gave out carbon dioxide and used none in the dark", [W("The pondweed made more oxygen in the dark than in the light", "wrong-idea", "No light means no photosynthesis, so no extra oxygen is made."), W("The pondweed took in carbon dioxide and gave out oxygen in the dark", "reversed", "Taking in carbon dioxide would turn the indicator purple."), W("The foil around the tube gave out carbon dioxide into the water", "wrong-idea", "Foil does not give out gases.")], ["In the dark there is no photosynthesis, but the pondweed still gives out carbon dioxide."], IND)
q("ph-204", C, 1, FT, "Using the same results, why were tubes C and D set up without pondweed?", "To show the colour change is caused by the pondweed", [W("To show that the foil gives out carbon dioxide", "wrong-reason", "The foil was not the thing being tested."), W("To make the other tubes turn purple", "wrong-reason", "The tubes were not meant to cause changes in other tubes."), W("To make the pondweed in A and B grow more", "wrong-reason", "Tubes C and D have no effect on A and B.")], ["Tubes C and D stayed red, so the indicator does not change by itself."], IND)
L4 = lambda: leaf([("P", "white", False), ("Q", "green", False), ("R", "green", True), ("S", "white", True)], "A leaf with green and white parts")
q("ph-205", C, 1, FT, "A plant with leaves that have green and white parts is kept in the dark for a day. A leaf is covered with foil as shown (hatched parts) and the plant is put in bright light. Which two parts should be compared to show that light is needed for a leaf to make starch?", "Q and R", [W("P and Q", "wrong-pair", "P and Q differ in colour, not in light."), W("P and S", "wrong-pair", "Both are white, so neither makes starch."), W("Q and S", "wrong-pair", "Both the colour and the light are different.")], ["Q and R are both green. Only the light is different."], L4)
q("ph-206", C, 1, FT, "For the same leaf, which two parts should be compared to show that the green parts are needed for a leaf to make starch?", "P and Q", [W("Q and R", "wrong-pair", "Q and R differ in light, not in colour."), W("R and S", "wrong-pair", "Both are covered, so neither gets light."), W("P and R", "wrong-pair", "Both the colour and the light are different.")], ["P and Q both get light. Only the colour is different."], L4)
q("ph-207", C, 1, PH, "The same leaf is tested for starch after several hours in bright light. Which part or parts turn blue-black?", "Q only", [W("P and Q", "wrong-part", "P is white, so it cannot make starch."), W("Q and R", "wrong-part", "R is covered, so it gets no light."), W("P, Q and R", "wrong-part", "P has no green and R gets no light.")], ["Only Q is both green and in the light."], L4)
OX = lambda: graph(["6 am", "10 am", "2 pm", "6 pm", "10 pm", "2 am"], [("o", [4, 7, 9, 8, 6, 4])], 10, "Time", "Oxygen in the water (units)", "Oxygen in a pond over a day and night", ystep=2, W=380, H=250)
q("ph-208", C, 1, RD, "The graph shows the amount of oxygen in a pond with water plants and fish. Which statement best explains why the amount of oxygen falls from 2 pm to 2 am?", "Less light means less oxygen is made but oxygen is still used", [W("The plants make more oxygen as it gets darker and cooler", "reversed", "Plants make oxygen only in the light."), W("The fish stop using oxygen once it gets dark at night", "wrong-idea", "Fish need oxygen all day and night."), W("The plants take in oxygen to make their food in the dark", "wrong-idea", "Plants give out oxygen when they make food.")], ["As the light fades photosynthesis slows and stops, but living things in the pond keep using oxygen."], OX)
q("ph-209", C, 1, RD, "Using the same graph, why is the amount of oxygen lowest at 6 am?", "There was no light all night, and oxygen was used up", [W("The plants made too much oxygen during the night", "wrong-idea", "Plants make oxygen only in the light."), W("The plants have been making oxygen in bright light", "wrong-idea", "It is still dark before dawn."), W("The fish gave out oxygen all night", "wrong-idea", "Fish take in oxygen. They do not give it out.")], ["Oxygen was used all night with no photosynthesis to replace it."], OX)
CO = lambda: graph(["6 am", "10 am", "2 pm", "6 pm", "10 pm"], [("c", [600, 450, 300, 400, 550])], 700, "Time", "Carbon dioxide (units)", "Carbon dioxide in a greenhouse", ystep=100, W=380, H=250)
q("ph-210", C, 1, RD, "The graph shows the carbon dioxide in a greenhouse full of plants. Why is the amount lowest at 2 pm?", "The plants are using carbon dioxide fastest in bright light", [W("The plants are giving out the most carbon dioxide at 2 pm", "reversed", "At 2 pm the carbon dioxide is at its lowest, so it is being used up."), W("The plants make no food at 2 pm", "wrong-idea", "Photosynthesis is fastest in bright light."), W("The plants are using oxygen fastest at 2 pm", "wrong-idea", "Plants make oxygen in bright light, and this does not lower the carbon dioxide.")], ["Bright light makes photosynthesis fast, so carbon dioxide is used up quickly."], CO)
SD = tb(["Pot", "Hours of light a day", "Water", "Mass gained in 2 weeks (g)"], [["A", "8", "plenty", "12"], ["B", "8", "little", "6"], ["C", "2", "plenty", "5"], ["D", "0", "plenty", "0"]], [50, 110, 70, 130], "Four pots of seedlings")
q("ph-211", C, 1, FT, "The table shows four pots of seedlings. Which two pots should be compared to find out whether the amount of light affects how much mass the seedlings gain?", "A and C", [W("A and B", "wrong-pair", "A and B differ in water, not in light."), W("B and C", "wrong-pair", "Both the light and the water are different."), W("B and D", "wrong-pair", "Both the light and the water are different.")], ["A and C have plenty of water and differ only in light."], SD)
q("ph-212", C, 1, RD, "Using the same table, which conclusion is best supported?", "Seedlings gain the most mass with enough light and water", [W("Seedlings gain the most mass in the dark", "reversed", "Pot D, in the dark, gained no mass."), W("The amount of water has no effect on the mass gained", "wrong-reading", "A gained twice the mass of B, which had less water."), W("The amount of light has no effect on the mass gained", "wrong-reading", "A, C and D differ in light and have very different masses.")], ["A had both enough light and plenty of water and gained the most mass."], SD)
q("ph-213", C, 1, FT, "Meng wants to find out if a plant needs carbon dioxide to make starch. He puts one plant in a jar with a dish that takes in carbon dioxide. Which should he keep the same in a second jar without the dish?", "The amount of light and the amount of water", [W("The amount of carbon dioxide", "changed-variable", "This is the factor being tested, so it must be different."), W("Whether there is a dish that takes in carbon dioxide", "changed-variable", "This is the change he makes on purpose."), W("The amount of starch in the leaves", "measured-variable", "This is what he finds out at the end.")], ["Only the carbon dioxide should change."], None)
q("ph-214", C, 1, PH, "A potted plant is sealed in a glass jar and kept in the dark for three days. What happens to the amount of oxygen and carbon dioxide in the jar?", "Oxygen decreases and carbon dioxide increases", [W("Oxygen increases and carbon dioxide decreases", "reversed", "In the dark there is no photosynthesis to make oxygen or use carbon dioxide."), W("Both oxygen and carbon dioxide increase", "wrong-idea", "The plant uses oxygen in the dark, so it does not increase."), W("Both stay the same", "wrong-idea", "The plant is alive and takes in oxygen and gives out carbon dioxide.")], ["With no photosynthesis, the plant still uses oxygen and gives out carbon dioxide."], lambda: jar(None, False, caption="A sealed jar in the dark"))
q("ph-215", C, 1, PH, "Two sealed bottles each contain a small fish and some pondweed. Bottle P is in bright light and bottle Q is in a dark cupboard. Which statement is most likely to be correct?", "The fish in Q will run out of oxygen sooner than the fish in P", [W("The fish in P will run out of oxygen sooner than the fish in Q", "reversed", "In bright light the pondweed in P makes oxygen."), W("The fish in both bottles will run out of oxygen at the same time", "wrong-idea", "Only P has light for photosynthesis."), W("The fish in Q will have more oxygen because the pondweed is resting", "wrong-idea", "The pondweed in the dark makes no oxygen and also uses some.")], ["In the dark no oxygen is made, so Q's fish and weed use it up sooner."], None)
q("ph-216", C, 1, RD, "In an earlier test, a pondweed gave out 24 bubbles per minute when the lamp was 20 cm away. The lamp is now moved to 10 cm, as shown. How many bubbles per minute are likely?", "More than 24", [W("Fewer than 24", "reversed", "A nearer lamp gives more light, so photosynthesis is faster."), W("Exactly 24", "wrong-idea", "The distance has changed, so the light on the plant has changed."), W("None", "wrong-idea", "The lamp is on and the pondweed is in the light.")], ["A nearer lamp gives brighter light, so more oxygen bubbles are given out."], lambda: pondweed(10, caption="The lamp is moved nearer"))
q("ph-217", C, 1, PH, "Which statement about a healthy plant in bright light is correct?", "It makes food in the light and uses some of its food for energy", [W("It makes food only and never uses any of its food", "wrong-idea", "Plants use food for energy all the time."), W("It uses food for energy only during the night", "wrong-idea", "Plants use food for energy day and night."), W("It makes food at night and stores it in the day", "wrong-idea", "Food is made only when there is light.")], ["Plants make food in the light, and use food for energy all the time."], None)
q("ph-218", C, 1, PH, "A sweet potato plant stores starch in its roots. Where did the plant first make the sugar that became this starch?", "In the leaves", [W("In the roots", "wrong-part", "Roots are underground in the dark, so they cannot photosynthesise."), W("In the soil", "wrong-part", "Soil does not make sugar."), W("In the stem under the soil", "wrong-part", "A stem under the soil gets no light.")], ["Sugar is made in the leaves in the light and carried down to the roots for storage."], None)
q("ph-219", C, 1, PH, "Water plants in a pond grow best in the water near the surface. Why?", "They get more light for photosynthesis near the surface", [W("They get more soil to grow in near the surface", "wrong-reason", "Soil is at the bottom of the pond."), W("They get much less carbon dioxide near the surface", "wrong-reason", "Less carbon dioxide would not help them."), W("They have no need for light, so depth does not matter", "wrong-reason", "Plants always need light to make food.")], ["Light cannot reach deep into the water."], None)
q("ph-220", C, 1, PH, "Which of the following would help a plant in a greenhouse to make more food?\nA: More light\nB: More water\nC: More carbon dioxide\nD: More oxygen", "A, B and C only", [W("A, B and D only", "wrong-need", "Oxygen is a product of photosynthesis, so more of it does not help."), W("B, C and D only", "wrong-need", "More light also helps, and more oxygen does not."), W("A and D only", "wrong-need", "Water and carbon dioxide help too, and oxygen does not.")], ["Light, water and carbon dioxide are what a plant needs."], None)
q("ph-221", C, 1, PH, "A plant has leaves with white patches. Why does it make less food than a plant with all-green leaves?", "The white parts cannot make food, so less of each leaf can", [W("The white parts take in much less water than green parts", "wrong-reason", "The roots take in the water."), W("The white parts make more oxygen than green parts do", "wrong-reason", "Parts that cannot make food make no oxygen."), W("The white parts block light from the green parts", "wrong-reason", "The white parts do not shade the green parts.")], ["Only the green parts make food."], None)
SU = lambda: graph(["0", "2", "4", "6", "8"], [("s", [0, 10, 20, 30, 40])], 50, "Hours of light", "Sugar made (units)", "Sugar made by a plant", ystep=10, W=360, H=250)
q("ph-222", C, 1, RD, "The graph shows the sugar made by a plant in different numbers of hours of light. How much sugar will be made in 5 hours, if the plant keeps making sugar in the same way?", "25 units", [W("20 units", "wrong-reading", "20 units is the amount for 4 hours."), W("30 units", "wrong-reading", "30 units is the amount for 6 hours."), W("50 units", "wrong-calc", "The plant makes 5 units in each hour, so 5 hours gives 25 units.")], ["The plant makes 5 units each hour, so in 5 hours it makes 25 units."], SU)
q("ph-223", C, 1, FT, "Hana sets up a pondweed under a funnel and test tube, and sees no bubbles. Which of the following is the most likely reason?", "The lamp was switched off", [W("The lamp was very bright", "wrong-reason", "Bright light makes more bubbles."), W("The pondweed had plenty of carbon dioxide", "wrong-reason", "Plenty of carbon dioxide would help, not stop, the bubbles."), W("The pondweed was in water", "wrong-reason", "Pondweed is a water plant, so water is what it needs.")], ["With no light there is no photosynthesis and no oxygen bubbles."], lambda: pondweed(20, caption="Pondweed under a funnel"))
q("ph-224", C, 1, FT, "Which is the best way to make the results of a pondweed bubble-counting experiment more reliable?", "Repeat each test several times and take the average", [W("Count the bubbles for only 5 seconds", "wrong-idea", "A short count gives less reliable results."), W("Use a different pondweed each time", "wrong-idea", "A different plant adds another difference between tests."), W("Change the lamp distance and the temperature together", "wrong-idea", "Changing two things at once makes the result unclear.")], ["Repeating gives an average that is less affected by one odd result."], None)
q("ph-225", C, 1, PH, "Which row correctly gives one raw material and one product of photosynthesis?", "Raw material: water; product: oxygen", [W("Raw material: oxygen; product: water", "reversed", "Oxygen is a product, not a raw material."), W("Raw material: sugar; product: carbon dioxide", "reversed", "Sugar is a product, and carbon dioxide is a raw material."), W("Raw material: carbon dioxide; product: water", "wrong-idea", "Water is a raw material, not a product.")], ["Water and carbon dioxide are raw materials. Sugar and oxygen are products."], None)
